class Solution {
    public List<String> fizzBuzz(int n){
        List<String> answer=new ArrayList<>();
        for(int value=1;value<=n;value++){
            if(value%15==0)answer.add("FizzBuzz");
            else if(value%3==0)answer.add("Fizz");
            else if(value%5==0)answer.add("Buzz");
            else answer.add(String.valueOf(value));
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun fizzBuzz(n:Int):List<String>{
        val answer=mutableListOf<String>();
        for(value in 1..n)answer.add(when{
            value%15==0->"FizzBuzz";
            value%3==0->"Fizz";
            value%5==0->"Buzz";
            else->value.toString()
        });
        return answer
    }
}

code.cpp:
class Solution {
    public: vector<string> fizzBuzz(int n){
        vector<string> answer;
        for(int value=1;value<=n;++value){
            if(value%15==0)answer.push_back("FizzBuzz");
            else if(value%3==0)answer.push_back("Fizz");
            else if(value%5==0)answer.push_back("Buzz");
            else answer.push_back(to_string(value));
        }
        return answer;
    }
};
